1	// PC Financial Credit Card CSV Parser
2	// Expected format: Description,Type,Card Holder Name,Date,Time,Amount
3	// Date format: MM/DD/YYYY
4	// Amount: negative for purchases, positive for refunds
5	
6	import { BaseCSVParser } from './BaseCSVParser';
7	import type { CSVParseResult, ParsedTransaction } from '$lib/models/Transaction';
8	
9	export class PCFinancialParser extends BaseCSVParser {
10		parse(csvContent: string): CSVParseResult {
11			const transactions: ParsedTransaction[] = [];
12			const errors: string[] = [];
13	
14			try {
15				csvContent = this.removeBOM(csvContent);
16				const rows = this.parseCSV(csvContent);
17	
18				if (rows.length < 2) {
19					errors.push('CSV file is empty or has no data rows');
20					return { transactions, errors };
21				}
22	
23				// Validate header
24				const header = rows[0];
25				if (!this.validateFormat(csvContent)) {
26					errors.push(
27						'Invalid PC Financial CSV format. Expected columns: Description, Type, Card Holder Name, Date, Time, Amount'
28					);
29					return { transactions, errors };
30				}
31	
32				// Find column indices
33				const descriptionIdx = header.findIndex((h) => h.toLowerCase().includes('description'));
34				const dateIdx = header.findIndex((h) => h.toLowerCase() === 'date');
35				const amountIdx = header.findIndex((h) => h.toLowerCase() === 'amount');
36	
37				// Parse data rows
38				for (let i = 1; i < rows.length; i++) {
39					const row = rows[i];
40					if (row.length < 6) continue; // Skip incomplete rows
41	
42					const description = row[descriptionIdx]?.trim();
43					const dateStr = row[dateIdx]?.trim();
44					const amountStr = row[amountIdx]?.trim();
45	
46					// Parse date
47					const transaction_date = this.parseDate(dateStr);
48					if (!transaction_date) {
49						errors.push(`Row ${i + 1}: Invalid date format "${dateStr}"`);
50						continue;
51					}
52	
53					// Parse amount
54					const rawAmount = this.parseAmount(amountStr);
55					if (rawAmount === null) {
56						errors.push(`Row ${i + 1}: Invalid amount "${amountStr}"`);
57						continue;
58					}
59	
60					// PC Financial uses negative for expenses — keep as-is (#{#trn2a})
61					const amount = this.normalizeAmount(rawAmount, false);
62	
63					// Validate description
64					if (!description) {
65						errors.push(`Row ${i + 1}: Missing vendor name/description`);
66						continue;
67					}
68	
69					transactions.push({
70						transaction_date,
71						vendor_name: description,
72						amount
73					});
74				}
75			} catch (e: any) {
76				errors.push(`Failed to parse CSV: ${e.message || 'Unknown error'}`);
77			}
78	
79			return { transactions, errors };
80		}
81	
82		validateFormat(csvContent: string): boolean {
83			try {
84				csvContent = this.removeBOM(csvContent);
85				const rows = this.parseCSV(csvContent);
86				if (rows.length === 0) return false;
87	
88				const header = rows[0];
89				const expectedColumns = ['description', 'type', 'card holder name', 'date', 'time', 'amount'];
90				return this.hasExpectedColumns(header, expectedColumns);
91			} catch {
92				return false;
93			}
94		}
95	}
