1	import { describe, it, expect } from 'vitest';
2	import { readFileSync } from 'fs';
3	import { join } from 'path';
4	import { PCFinancialParser } from '../PCFinancialParser';
5	
6	describe('PCFinancialParser', () => {
7		const parser = new PCFinancialParser();
8	
9		// Helper to load CSV files from resources
10		const loadCSV = (filename: string): string => {
11			const filePath = join(process.cwd(), 'resources', filename);
12			return readFileSync(filePath, 'utf-8');
13		};
14	
15		describe('validateFormat', () => {
16			it('should validate correct PC Financial CSV format', () => {
17				const csv = loadCSV('PCFInancialSample.csv');
18				expect(parser.validateFormat(csv)).toBe(true);
19			});
20	
21			it('should reject invalid CSV format', () => {
22				const invalidCSV = `Date,Merchant,Amount
23	01/01/2024,Store,100.00`;
24				expect(parser.validateFormat(invalidCSV)).toBe(false);
25			});
26	
27			it('should reject empty CSV', () => {
28				expect(parser.validateFormat('')).toBe(false);
29			});
30	
31			it('should handle CSV with BOM', () => {
32				const csv = loadCSV('PCFInancialSample.csv');
33				expect(parser.validateFormat(csv)).toBe(true);
34			});
35		});
36	
37		describe('parse', () => {
38			it('should parse sample data correctly', () => {
39				const csv = loadCSV('PCFInancialSample.csv');
40				const result = parser.parse(csv);
41	
42				expect(result.errors).toEqual([]);
43				expect(result.transactions).toHaveLength(17);
44	
45				// Check first transaction (expense - stays negative) #{#trn2a}
46				expect(result.transactions[0]).toEqual({
47					transaction_date: '2024-06-26',
48					vendor_name: 'RCSS SOUTH KANATA',
49					amount: -268.29 // Native sign: negative = expense
50				});
51	
52				// Check last transaction (refund - stays positive) #{#trn2a}
53				expect(result.transactions[16]).toEqual({
54					transaction_date: '2024-02-16',
55					vendor_name: 'RCSS SOUTH KANATA',
56					amount: 22.85 // Native sign: positive = refund
57				});
58			});
59	
60			it('should keep expenses as negative amounts (#{#trn2a})', () => {
61				const csv = loadCSV('PCFInancialSample.csv');
62				const result = parser.parse(csv);
63				// Native signs kept: expenses stay negative
64				const expenseTransactions = result.transactions.filter((t) => t.amount < 0);
65				expect(expenseTransactions).toHaveLength(16);
66			});
67	
68			it('should keep refunds as positive amounts (#{#trn2a})', () => {
69				const csv = loadCSV('PCFInancialSample.csv');
70				const result = parser.parse(csv);
71				// Native signs kept: refunds stay positive
72				const refundTransactions = result.transactions.filter((t) => t.amount > 0);
73				expect(refundTransactions).toHaveLength(1);
74				expect(refundTransactions[0].amount).toBe(22.85); // Native sign: positive = refund
75			});
76	
77			it('should parse dates in MM/DD/YYYY format', () => {
78				const csv = `Description,Type,Card Holder Name,Date,Time,Amount
79	Test Store,PURCHASE,MARK,12/31/2023,11:59 PM,-100.00`;
80				const result = parser.parse(csv);
81	
82				expect(result.transactions[0].transaction_date).toBe('2023-12-31');
83			});
84	
85			it('should handle amounts without decimals', () => {
86				const csv = `Description,Type,Card Holder Name,Date,Time,Amount
87	Test Store,PURCHASE,MARK,06/05/2024,4:44 PM,-226`;
88				const result = parser.parse(csv);
89	
90				expect(result.transactions[0].amount).toBe(-226); // Native sign: negative = expense
91			});
92	
93			it('should report errors for invalid dates', () => {
94				const csv = `Description,Type,Card Holder Name,Date,Time,Amount
95	Test Store,PURCHASE,MARK,invalid-date,11:59 PM,-100.00`;
96				const result = parser.parse(csv);
97	
98				expect(result.errors.length).toBeGreaterThan(0);
99				expect(result.errors[0]).toContain('Invalid date format');
100			});
101	
102			it('should report errors for invalid amounts', () => {
103				const csv = `Description,Type,Card Holder Name,Date,Time,Amount
104	Test Store,PURCHASE,MARK,06/01/2024,11:59 PM,not-a-number`;
105				const result = parser.parse(csv);
106	
107				expect(result.errors.length).toBeGreaterThan(0);
108				expect(result.errors[0]).toContain('Invalid amount');
109			});
110	
111			it('should report errors for missing vendor name', () => {
112				const csv = `Description,Type,Card Holder Name,Date,Time,Amount
113	,PURCHASE,MARK,06/01/2024,11:59 PM,-100.00`;
114				const result = parser.parse(csv);
115	
116				expect(result.errors.length).toBeGreaterThan(0);
117				expect(result.errors[0]).toContain('Missing vendor name');
118			});
119	
120			it('should handle empty CSV', () => {
121				const result = parser.parse('');
122	
123				expect(result.transactions).toEqual([]);
124				expect(result.errors.length).toBeGreaterThan(0);
125			});
126	
127			it('should skip incomplete rows', () => {
128				const csv = `Description,Type,Card Holder Name,Date,Time,Amount
129	Test Store,PURCHASE,MARK,06/01/2024,11:59 PM,-100.00
130	Incomplete Row
131	Another Store,PURCHASE,MARK,06/02/2024,10:00 AM,-50.00`;
132				const result = parser.parse(csv);
133	
134				expect(result.transactions).toHaveLength(2);
135				expect(result.transactions[0].vendor_name).toBe('Test Store');
136				expect(result.transactions[1].vendor_name).toBe('Another Store');
137			});
138	
139			it('should handle CSV with BOM', () => {
140				const csv = loadCSV('PCFInancialSample.csv');
141				const result = parser.parse(csv);
142	
143				expect(result.transactions).toHaveLength(17);
144				expect(result.errors).toEqual([]);
145			});
146		});
147	});
